const STEPS = {"1":{title:"\u5f15\u5165 Maven \u4f9d\u8d56",desc:"Spring Boot + AgentScope Harness \u5b8c\u6574\u4f9d\u8d56\u914d\u7f6e\u3002",tabs:{"pom.xml":"<parent>\n    <groupId>org.springframework.boot</groupId>\n    <artifactId>spring-boot-starter-parent</artifactId>\n    <version>4.0.3</version>\n</parent>\n\n<dependencies>\n    <!-- Spring Boot WebFlux: \u54cd\u5e94\u5f0fWeb\u6846\u67b6, SSE\u6d41\u5f0f\u63a8\u9001\u7684\u5fc5\u8981\u524d\u63d0 -->\n    <dependency>\n        <groupId>org.springframework.boot</groupId>\n        <artifactId>spring-boot-starter-webflux</artifactId>\n    </dependency>\n\n    <!-- AgentScope Harness: \u63a8\u8350\u5165\u53e3,\u81ea\u52a8\u62c9\u5165agentscope-core\n         \u542b: \u5de5\u4f5c\u533a\u9a71\u52a8\u4eba\u683c/\u4f1a\u8bdd\u6301\u4e45\u5316/\u53cc\u5c42\u8bb0\u5fc6/\u5b50Agent/\u6c99\u7bb1/PlanMode/Skill -->\n    <dependency>\n        <groupId>io.agentscope</groupId>\n        <artifactId>agentscope-harness</artifactId>\n        <version>2.0.0-RC1</version>\n    </dependency>\n</dependencies>","application.yml":"server:\n  port: 8888\n\nagentscope:\n  workspace: .agentscope/workspace  # \u5de5\u4f5c\u533a\u6839\u76ee\u5f55, \u6240\u6709\u72b6\u6001\u6587\u4ef6\u5b58\u653e\u4e8e\u6b64"},tip:"Spring Boot 4.0.3 + AgentScope 2.0.0-RC1\u3002WebFlux\u662fSSE\u6d41\u5f0f\u63a5\u53e3\u7684\u524d\u63d0\u3002\u53ea\u8dd1\u88f8ReActAgent\u53ef\u5355\u72ec\u4f9d\u8d56agentscope-core\u3002"},"2":{title:"@Bean \u521b\u5efa Agent",desc:"\u5c06Agent\u6ce8\u518c\u4e3aSpring Bean,\u5168\u5c40\u5355\u4f8b,Controller\u53ef\u76f4\u63a5\u6ce8\u5165\u3002HarnessAgent\u7ebf\u7a0b\u5b89\u5168,\u4e0d\u540c\u7528\u6237\u901a\u8fc7RuntimeContext\u9694\u79bb\u3002",tabs:{"AgentConfig.java":"import io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class AgentConfig {\n\n    @Bean  // \u6ce8\u518c\u4e3aSpring Bean, Controller\u53ef\u901a\u8fc7\u6784\u9020\u5668\u6ce8\u5165\n    public HarnessAgent assistantAgent() {\n        return HarnessAgent.builder()\n                .name(\"assistant\")                        // Agent\u6807\u8bc6\u7b26,\u7528\u4e8e\u65e5\u5fd7\u548c\u6d88\u606f\n                .sysPrompt(\"\u4f60\u662f\u4e00\u4e2a\u6709\u5e2e\u52a9\u7684\u52a9\u624b\u3002\")        // \u57fa\u7840\u7cfb\u7edf\u63d0\u793a\u8bcd,\u6bcf\u8f6e\u63a8\u7406\u524d\u62fc\u5165system\u6d88\u606f\n                .model(\"dashscope:qwen-plus\")              // \u6a21\u578bID,\u7531ModelRegistry\u81ea\u52a8\u89e3\u6790\n                                                             // \u81ea\u52a8\u8bfb\u53d6DASHSCOPE_API_KEY\u73af\u5883\u53d8\u91cf\n                .workspace(Paths.get(\".agentscope/workspace\"))  // \u5de5\u4f5c\u533a\u8def\u5f84\n                .build();\n    }\n}","ChatController.java":"import io.agentscope.core.agent.RuntimeContext;   // per-call\u5143\u6570\u636e\u888b,\u4e0d\u6301\u4e45\u5316\nimport io.agentscope.core.message.Msg;                // \u4e00\u6b21\u5b8c\u6574\u5bf9\u8bdd\u8f6e\u6b21\u7684\u8f7d\u4f53\nimport io.agentscope.core.message.UserMessage;         // \u7528\u6237\u6d88\u606f,\u81ea\u52a8\u5305\u88c5\u4e3aTextBlock\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.web.bind.annotation.*;\nimport reactor.core.publisher.Mono;                    // \u54cd\u5e94\u5f0f\u5355\u503c\nimport java.util.List;\n\n@RestController\n@RequestMapping(\"/api/chat\")\npublic class ChatController {\n\n    private final HarnessAgent agent;\n\n    // Spring\u81ea\u52a8\u6ce8\u5165\u4e0a\u9762@Bean\u5b9a\u4e49\u7684HarnessAgent\n    public ChatController(HarnessAgent assistantAgent) {\n        this.agent = assistantAgent;\n    }\n\n    /** \u540c\u6b65\u8c03\u7528: \u9a71\u52a8ReAct\u63a8\u7406-\u884c\u52a8\u5faa\u73af,\u8fd4\u56de\u6700\u7ec8assistant Msg */\n    @PostMapping(\"/send\")\n    public Mono<String> chat(@RequestBody String message,\n                             @RequestParam(defaultValue = \"default\") String sessionId,\n                             @RequestParam(defaultValue = \"user\") String userId) {\n        // RuntimeContext: per-call\u5143\u6570\u636e,\u8c03\u7528\u7ed3\u675f\u540e\u81ea\u52a8\u89e3\u7ed1\n        // sessionId\u51b3\u5b9a\u5bf9\u8bdd(AgentState\u52a0\u8f7d/\u4fdd\u5b58key), userId\u51b3\u5b9a\u6587\u4ef6\u547d\u540d\u7a7a\u95f4(\u591a\u79df\u6237\u9694\u79bb)\n        RuntimeContext ctx = RuntimeContext.builder()\n                .sessionId(sessionId).userId(userId).build();\n\n        return agent.call(List.of(new UserMessage(message)), ctx)\n                .map(Msg::getTextContent);  // \u63d0\u53d6\u6587\u672c\u5185\u5bb9\u8fd4\u56de\n    }\n}"},tip:"HarnessAgent\u7ebf\u7a0b\u5b89\u5168\u5355\u4f8b\u3002model()\u5b57\u7b26\u4e32\u7531ModelRegistry\u89e3\u6790,\u81ea\u52a8\u8bfb\u73af\u5883\u53d8\u91cf\u53d6API Key\u3002\u663e\u5f0fModelBuilder\u53ef\u7cbe\u7ec6\u63a7\u5236\u8d85\u65f6/endpoint\u3002"},"3":{title:"\u6ce8\u518c\u81ea\u5b9a\u4e49 Tool",desc:"@Tool\u6ce8\u89e3\u5f0f\u6700\u8f7b\u91cf(\u81ea\u52a8\u63a8\u5bfcJSONSchema); ToolBase\u7ee7\u627f\u5f0f\u53ef\u81ea\u5b9a\u4e49\u6743\u9650\u68c0\u67e5; ToolGroup\u6309\u7ec4\u6fc0\u6d3b/\u505c\u7528\u3002",tabs:{"@Tool \u6ce8\u89e3\u5f0f":"import io.agentscope.core.tool.Tool;       // @Tool\u6ce8\u89e3: \u6807\u8bb0\u65b9\u6cd5\u4e3a\u53ef\u88abLLM\u8c03\u7528\u7684\u5de5\u5177\nimport io.agentscope.core.tool.ToolParam;  // @ToolParam\u6ce8\u89e3: \u63cf\u8ff0\u5de5\u5177\u53c2\u6570,\u81ea\u52a8\u751f\u6210JSONSchema\nimport org.springframework.stereotype.Component;\n\n@Component  // \u6ce8\u518c\u4e3aSpring Bean,\u4f9bToolkit @Bean\u6ce8\u5165\npublic class SimpleTools {\n\n    @Tool(name = \"get_current_time\",                              // \u66b4\u9732\u7ed9LLM\u7684\u5de5\u5177\u540d\n          description = \"Returns the current time in a given IANA timezone.\",  // LLM\u6839\u636e\u6b64\u63cf\u8ff0\u51b3\u5b9a\u662f\u5426\u8c03\u7528\n          readOnly = true,                                        // \u53ea\u8bfb\u6807\u8bb0: EXPLORE\u6a21\u5f0f\u4e0b\u81ea\u52a8\u653e\u884c\n          concurrencySafe = true)                                  // \u5e76\u53d1\u5b89\u5168: \u5141\u8bb8\u591a\u4e2a\u5de5\u5177\u5e76\u884c\u6267\u884c\n    public String getCurrentTime(\n            @ToolParam(name = \"timezone\", description = \"IANA timezone, e.g. Asia/Shanghai\")\n            String timezone) {\n        return java.time.LocalDateTime.now(java.time.ZoneId.of(timezone))\n                .format(java.time.format.DateTimeFormatter.ISO_LOCAL_DATE_TIME);\n    }\n}","AgentConfig\u6ce8\u518cToolkit":"import io.agentscope.core.tool.Toolkit;  // \u5de5\u5177\u5bb9\u5668: \u7ba1\u7406\u6ce8\u518c/\u5206\u53d1/JSONSchema\u66b4\u9732\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class AgentConfig {\n\n    @Bean\n    public Toolkit toolkit(SimpleTools simpleTools) {\n        Toolkit toolkit = new Toolkit();             // \u521b\u5efa\u7a7a\u5de5\u5177\u5bb9\u5668\n        toolkit.registerTool(simpleTools);            // \u53cd\u5c04\u6ce8\u518c: \u626b\u63cf@Tool\u65b9\u6cd5,\u81ea\u52a8\u63a8\u5bfc\u53c2\u6570Schema\n        // toolkit.registerMcpClient(mcp).block();   // \u6ce8\u518cMCP\u5ba2\u6237\u7aef\n        // toolkit.registerToolGroup(group);         // \u6ce8\u518c\u5de5\u5177\u7ec4\n        return toolkit;\n    }\n\n    @Bean\n    public HarnessAgent assistantAgent(Toolkit toolkit) {\n        return HarnessAgent.builder()\n                .name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .toolkit(toolkit)  // \u6ce8\u5165\u5de5\u5177\u5bb9\u5668,Agent\u5728\u63a8\u7406\u65f6\u53ef\u8c03\u7528\u5176\u4e2d\u6ce8\u518c\u7684\u6240\u6709\u5de5\u5177\n                .build();\n    }\n}","ToolBase\u7ee7\u627f\u5f0f(\u81ea\u5b9a\u4e49\u6743\u9650)":"import io.agentscope.core.message.TextBlock;\nimport io.agentscope.core.message.ToolResultBlock;\nimport io.agentscope.core.permission.PermissionDecision; // \u4e09\u6001\u51b3\u7b56: ALLOW/DENY/ASK\nimport io.agentscope.core.tool.ToolBase;                // \u5de5\u5177\u62bd\u8c61\u57fa\u7c7b\nimport io.agentscope.core.tool.ToolCallParam;\nimport io.agentscope.core.tool.ToolExecutionContext;\nimport org.springframework.stereotype.Component;\nimport reactor.core.publisher.Mono;\nimport java.util.List;\nimport java.util.Map;\n\n@Component\npublic class WebSearchTool extends ToolBase {\n\n    public WebSearchTool() {\n        super(ToolBase.builder()\n                .name(\"web_search\")                      // \u5de5\u5177\u540d\n                .description(\"Search the web.\")          // LLM\u53ef\u89c1\u7684\u63cf\u8ff0\n                .inputSchema(Map.of(                     // \u624b\u52a8\u5b9a\u4e49JSONSchema\n                        \"type\", \"object\",\n                        \"properties\", Map.of(\"query\", Map.of(\"type\", \"string\")),\n                        \"required\", List.of(\"query\")))\n                .readOnly(true)\n                .concurrencySafe(true));\n    }\n\n    @Override\n    public Mono<PermissionDecision> checkPermissions(\n            Map<String, Object> toolInput, ToolExecutionContext context) {\n        // \u8fd0\u884c\u65f6\u6743\u9650\u68c0\u67e5,\u4e0d\u53ef\u7ed5\u8fc7(\u5373\u4f7fBYPASS\u6a21\u5f0f\u4e5f\u751f\u6548)\n        return Mono.just(PermissionDecision.allow(\"Web search is read-only.\"));\n    }\n\n    @Override\n    public Mono<ToolResultBlock> callAsync(ToolCallParam param) {\n        String query = (String) param.getInput().get(\"query\");\n        return doSearch(query).map(text -> ToolResultBlock.builder()\n                .id(param.getId()).name(getName())\n                .output(List.of(TextBlock.builder().text(text).build()))\n                .build());\n    }\n\n    private Mono<String> doSearch(String query) {\n        return Mono.just(\"Results for: \" + query);\n    }\n}","ToolGroup + MetaTool":"import io.agentscope.core.tool.Toolkit;\nimport io.agentscope.core.tool.ToolGroup;          // \u5de5\u5177\u7ec4: \u5e26\u540d\u79f0\u7684tool/MCP/skill\u96c6\u5408\nimport io.agentscope.core.tool.ToolGroupScope;     // \u4f5c\u7528\u57df: SESSION/GLOBAL\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class ToolGroupConfig {\n\n    @Bean\n    public Toolkit toolkit() {\n        Toolkit toolkit = new Toolkit();\n        toolkit.registerTool(new Object());  // basic\u7ec4\u59cb\u7ec8\u6fc0\u6d3b\n\n        // \u5b9a\u4e49database\u7ec4: \u6309\u4efb\u52a1\u6fc0\u6d3b/\u505c\u7528,\u4fdd\u6301\u4e0a\u4e0b\u6587\u805a\u7126\n        ToolGroup database = new ToolGroup(\n                \"database\", \"Tools for database operations.\",\n                ToolGroupScope.SESSION, false);  // SESSION:\u5f53\u524d\u4f1a\u8bdd\u6709\u6548\n        database.addTool(\"db_query\");\n        database.addTool(\"db_migrate\");\n        toolkit.registerToolGroup(database);\n\n        ToolGroup deployment = new ToolGroup(\n                \"deployment\", \"Tools for deploying services.\",\n                ToolGroupScope.SESSION, false);\n        deployment.addTool(\"deploy\");\n        deployment.addTool(\"rollback\");\n        toolkit.registerToolGroup(deployment);\n\n        return toolkit;\n    }\n\n    @Bean\n    public HarnessAgent assistantAgent(Toolkit toolkit) {\n        return HarnessAgent.builder()\n                .name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .toolkit(toolkit)\n                .enableMetaTool(true)   // \u542f\u7528meta tool: Agent\u8fd0\u884c\u65f6\u81ea\u6211\u7ba1\u7406\u5de5\u5177\u7ec4\n                .build();\n        // Agent\u8c03\u7528reset_tools\u58f0\u660e\u671f\u671b\u6fc0\u6d3b\u7684\u7ec4:\n        // reset_tools database=true deployment=false\n        // \u672a\u663e\u5f0f\u7f6etrue\u7684\u7ec4\u5168\u90e8\u505c\u7528,\u4e0d\u662f\u589e\u91cf\u5207\u6362!\n    }\n}"},tip:"@Tool\u6ce8\u89e3\u5f0f\u81ea\u52a8\u63a8\u5bfcSchema\u6700\u8f7b\u91cf; ToolBase\u7ee7\u627f\u5f0f\u81ea\u5b9a\u4e49\u6743\u9650/\u5916\u90e8\u6267\u884c; ToolGroup\u6309\u4efb\u52a1\u805a\u7126\u3002Context\u81ea\u52a8\u6ce8\u5165: \u672a\u6807@ToolParam\u7684\u53c2\u6570\u7531\u6846\u67b6\u6309\u7c7b\u578b\u81ea\u52a8\u6ce8\u5165(RuntimeContext/Agent/AgentState/\u81ea\u5b9a\u4e49POJO)\u3002"},"4":{title:"\u5199 AGENTS.md + tools.json",desc:"\u5de5\u4f5c\u533a\u6839\u76ee\u5f55\u6587\u4ef6\u6bcf\u8f6e\u63a8\u7406\u81ea\u52a8\u6ce8\u5165system prompt\u3002AGENTS.md\u6ce8\u5165\u4e3a<agents>\u5757; tools.json\u5728build()\u65f6\u4e00\u6b21\u6027\u8bfb\u53d6\u6ce8\u518cMCP\u5e76\u5e94\u7528\u767d\u540d\u5355\u3002",tabs:{"workspace/AGENTS.md":"# Assistant\n\n\u4f60\u662f\u4e00\u4e2a\u4e13\u4e1a\u7684\u6280\u672f\u52a9\u624b\u3002\n\n## \u884c\u4e3a\u7ea6\u5b9a\n- \u7528\u4e2d\u6587\u56de\u7b54\n- \u5bf9\u4e0d\u786e\u5b9a\u7684\u4fe1\u606f\u4e3b\u52a8\u8be2\u95ee\u786e\u8ba4\n- \u5173\u952e\u4fe1\u606f\u52a0\u7c97\u6807\u6ce8\n\n<!-- \u6b64\u6587\u4ef6\u6bcf\u8f6e\u63a8\u7406\u65f6\u5168\u6587\u6ce8\u5165system prompt\u7684<agents>\u5757 -->\n<!-- \u4fee\u6539\u540e\u7acb\u523b\u751f\u6548,\u65e0\u9700\u91cd\u542fAgent -->","workspace/knowledge/KNOWLEDGE.md":"# \u9886\u57df\u77e5\u8bc6\n\n## \u53ef\u7528\u53c2\u8003\n- api-reference.md -- API\u63a5\u53e3\u89c4\u8303\n- coding-standards.md -- \u7f16\u7801\u89c4\u8303\n\n<!-- KNOWLEDGE.md\u5168\u6587\u6ce8\u5165prompt -->\n<!-- \u5176\u4ed6\u6587\u4ef6\u53ea\u5217\u8def\u5f84\u6e05\u5355,Agent\u9700\u8981\u65f6\u901a\u8fc7read_file\u6309\u9700\u8bfb\u53d6 -->","workspace/tools.json":"{\n  \"allow\": [\"read_file\", \"grep_files\", \"execute\", \"memory_search\",\n            \"get_current_time\", \"web_search\"],\n  \"deny\": [],\n  \"mcpServers\": {\n    \"amap\": {\n      \"transport\": \"streamableHttp\",\n      \"url\": \"https://mcp.amap.com/mcp?key=${AMAP_API_KEY}\"\n    }\n  }\n}\n<!-- allow: \u975e\u7a7a\u65f6\u53ea\u5141\u8bb8\u5217\u51fa\u7684\u5de5\u5177\u66b4\u9732\u7ed9LLM(\u4e5f\u4f1a\u8fc7\u6ee4\u5185\u7f6e\u5de5\u5177!) -->\n<!-- deny: \u5217\u51fa\u7684\u5de5\u5177\u4e00\u5f8b\u4e0d\u66b4\u9732,\u4f18\u5148\u7ea7\u9ad8\u4e8eallow -->\n<!-- mcpServers: \u6784\u5efa\u671f\u4e00\u6b21\u6027\u6ce8\u518c\u5230Toolkit -->\n<!-- ${ENV_VAR}: \u73af\u5883\u53d8\u91cf\u66ff\u6362,\u672a\u8bbe\u7f6e\u65f6\u66ff\u6362\u6210\u7a7a\u4e32 -->"},tip:"AGENTS.md\u662f\u552f\u4e00\u5fc5\u5199\u7684\u3002allow\u767d\u540d\u5355\u4f1a\u8fc7\u6ee4\u5185\u7f6e\u5de5\u5177,\u52a1\u5fc5\u628aread_file/memory_search\u7b49\u4e00\u5e76\u5217\u51fa\u3002"},"5":{title:"REST API \u8c03\u7528 Agent",desc:"agent.call()\u8fd4\u56deMono<Msg>\u9002\u5408\u540c\u6b65; agent.streamEvents()\u8fd4\u56deFlux<AgentEvent>\u9002\u5408SSE\u5b9e\u65f6\u63a8\u9001\u3002RuntimeContext\u901a\u8fc7\u8bf7\u6c42\u53c2\u6570\u4f20\u5165\u5b9e\u73b0\u591a\u79df\u6237\u9694\u79bb\u3002",tabs:{"ChatController.java":"import io.agentscope.core.agent.RuntimeContext;\nimport io.agentscope.core.event.*;                      // \u6240\u6709\u4e8b\u4ef6\u7c7b\u578b\nimport io.agentscope.core.message.Msg;\nimport io.agentscope.core.message.UserMessage;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.codec.ServerSentEvent;\nimport org.springframework.web.bind.annotation.*;\nimport reactor.core.publisher.Flux;\nimport reactor.core.publisher.Mono;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n@RestController\n@RequestMapping(\"/api/chat\")\npublic class ChatController {\n\n    private final HarnessAgent agent;\n    public ChatController(HarnessAgent a) { this.agent = a; }\n\n    /** \u540c\u6b65\u8c03\u7528: \u7b49\u5f85Agent\u5b8c\u6210\u63a8\u7406\u540e\u8fd4\u56de\u5b8c\u6574\u6587\u672c */\n    @PostMapping(\"/send\")\n    public Mono<Map<String, String>> send(@RequestBody String message,\n                                          @RequestParam(defaultValue=\"default\") String sessionId,\n                                          @RequestParam(defaultValue=\"user\") String userId) {\n        RuntimeContext ctx = RuntimeContext.builder()\n                .sessionId(sessionId).userId(userId).build();\n        return agent.call(List.of(new UserMessage(message)), ctx)\n                .map(msg -> Map.of(\"reply\", msg.getTextContent(), \"sessionId\", sessionId));\n    }\n\n    /** \u6d41\u5f0f\u8c03\u7528: SSE\u5b9e\u65f6\u63a8\u9001Agent\u7684\u6bcf\u4e00\u6b65\u52a8\u4f5c */\n    @GetMapping(value=\"/stream\", produces=MediaType.TEXT_EVENT_STREAM_VALUE)\n    public Flux<ServerSentEvent<String>> stream(@RequestParam String message,\n                                                @RequestParam(defaultValue=\"default\") String sessionId,\n                                                @RequestParam(defaultValue=\"user\") String userId) {\n        RuntimeContext ctx = RuntimeContext.builder().sessionId(sessionId).userId(userId).build();\n        return agent.streamEvents(new UserMessage(message), ctx)\n                .map(event -> {\n                    Map<String, Object> p = new LinkedHashMap<>();\n                    p.put(\"type\", event.getType().name());\n                    if (event instanceof TextBlockDeltaEvent d) p.put(\"delta\", d.getDelta());\n                    else if (event instanceof ToolCallStartEvent t) p.put(\"tool\", t.getToolCallName());\n                    else if (event instanceof AgentEndEvent) p.put(\"done\", true);\n                    try { return ServerSentEvent.<String>builder()\n                            .data(new com.fasterxml.jackson.databind.ObjectMapper()\n                                    .writeValueAsString(p)).build();\n                    } catch (Exception e) { return ServerSentEvent.<String>builder().data(\"{}\").build(); }\n                });\n    }\n}"},tip:"call()\u9002\u5408\u7f16\u7a0b\u5f0f; streamEvents()\u9002\u5408\u524d\u7aef\u5b9e\u65f6\u6e32\u67d3\u3002\u4e8b\u4ef6\u7c7b\u578b: TEXT_BLOCK_DELTA/TOOL_CALL_START/TOOL_RESULT_END/AGENT_END\u3002"},"6":{title:"\u5f00\u542f\u8bb0\u5fc6\u538b\u7f29",desc:"\u53cc\u5c42\u8bb0\u5fc6: \u65e5\u6d41\u6c34\u8d26(memory/YYYY-MM-DD.md)\u53ea\u8ffd\u52a0; \u7b56\u5212\u540e\u957f\u671f\u8bb0\u5fc6(MEMORY.md)\u6bcf\u8f6e\u6ce8\u5165system prompt\u3002\u56db\u91cd\u538b\u7f29\u7b56\u7565\u6b63\u4ea4\u7ec4\u5408\u3002",tabs:{"AgentConfig.java":"import io.agentscope.harness.agent.HarnessAgent;\nimport io.agentscope.harness.agent.memory.compaction.CompactionConfig;\nimport io.agentscope.harness.agent.memory.compaction.ToolResultEvictionConfig;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class AgentConfig {\n\n    @Bean\n    public HarnessAgent assistantAgent() {\n        return HarnessAgent.builder()\n                .name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                // \u5bf9\u8bdd\u6458\u8981\u538b\u7f29\n                .compaction(CompactionConfig.builder()\n                        .triggerMessages(30)       // \u6d88\u606f\u6570\u8fbe\u523030\u6761\u89e6\u53d1\u538b\u7f29\n                        .keepMessages(10)          // \u538b\u7f29\u540e\u4fdd\u7559\u6700\u8fd110\u6761\u539f\u6587\n                        .triggerTokens(80_000)     // \u4f30\u7b97token\u8fbe\u523080K\u4e5f\u53ef\u89e6\u53d1\n                        .flushBeforeCompact(true)  // \u538b\u7f29\u524d\u4e8b\u5b9e\u5199\u5165\u65e5\u6d41\u6c34\u8d26\n                        .offloadBeforeCompact(true)// \u538b\u7f29\u524d\u5b58\u6c38\u4e0d\u538b\u7f29\u65e5\u5fd7\n                        .truncateArgs(CompactionConfig.TruncateArgsConfig.builder()\n                                .maxArgLength(2000).truncationText(\"...[truncated]...\")\n                                .build())\n                        .build())\n                // \u5927\u5de5\u5177\u7ed3\u679c\u5378\u8f7d: \u8d8580K\u5b57\u7b26\u7684\u7ed3\u679c\u843d\u76d8+\u5360\u4f4d\u7b26\n                .toolResultEviction(ToolResultEvictionConfig.defaults())\n                .build();\n    }\n}"},tip:"\u56db\u5957\u7b56\u7565\u6b63\u4ea4\u53ef\u7ec4\u5408,\u9ed8\u8ba4\u5168\u5173\u3002flushBeforeCompact\u4fdd\u8bc1\u538b\u7f29\u524d\u4e8b\u5b9e\u5148\u6c89\u6dc0\u5230MEMORY.md\u3002\u6ea2\u51fa\u515c\u5e95: compaction\u5f00\u4e86\u5c31\u81ea\u52a8\u751f\u6548\u3002"},"7":{title:"\u63a5\u5165 MCP Server",desc:"MCP (Model Context Protocol) \u6807\u51c6\u5316\u5de5\u5177\u534f\u8bae\u3002AgentScope\u81ea\u52a8\u5904\u7406\u534f\u8bae\u534f\u5546\u3001\u5de5\u5177\u53d1\u73b0\u4e0e\u7ed3\u679c\u8f6c\u6362\u3002\u652f\u6301STDIO/SSE/StreamableHTTP\u3002",tabs:{"McpConfig.java":"import io.agentscope.core.tool.Toolkit;\nimport io.agentscope.core.tool.mcp.McpClientBuilder;\nimport io.agentscope.core.tool.mcp.McpClientWrapper;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class McpConfig {\n\n    @Bean\n    public Toolkit toolkit() {\n        Toolkit toolkit = new Toolkit();\n\n        // Streamable HTTP: \u8fdc\u7a0bHTTP\u957f\u8fde\u63a5(\u63a8\u8350)\n        McpClientWrapper weather = McpClientBuilder.streamableHttp()\n                .name(\"weather\").url(\"https://api.weather.com/mcp\")\n                .header(\"Authorization\", \"Bearer \" + System.getenv(\"WEATHER_API_KEY\"))\n                .build();\n        toolkit.registerMcpClient(weather).block();\n\n        // STDIO: \u672c\u5730\u8fdb\u7a0bstdin/stdout\n        McpClientWrapper fs = McpClientBuilder.stdio()\n                .name(\"filesystem\").command(\"mcp-server-filesystem\")\n                .args(\"--root\", \"/project\").build();\n        toolkit.registerMcpClient(fs).block();\n\n        // SSE: \u8fdc\u7a0bHTTP SSE\u8fde\u63a5\n        McpClientWrapper search = McpClientBuilder.sse()\n                .name(\"search\").url(\"https://api.search.com/mcp/sse\").build();\n        toolkit.registerMcpClient(search).block();\n\n        return toolkit;\n    }\n\n    @Bean\n    public HarnessAgent assistantAgent(Toolkit toolkit) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).toolkit(toolkit).build();\n    }\n}","pom.xml(MCP\u4f9d\u8d56)":"<!-- MCP SDK: \u63a5\u5165STDIO/SSE/StreamableHTTP\u7684\u4f9d\u8d56 -->\n<dependency>\n    <groupId>io.modelcontextprotocol</groupId>\n    <artifactId>mcp</artifactId>\n    <version>0.7.0</version>\n</dependency>\n<!-- AgentScope MCP\u96c6\u6210 -->\n<dependency>\n    <groupId>io.agentscope</groupId>\n    <artifactId>agentscope-extensions-protocol-mcp</artifactId>\n    <version>2.0.0-RC1</version>\n</dependency>"},tip:"MCP tool\u547d\u540d\u4e3amcp_{server}_{tool}\u3002readOnlyHint\u7684\u5de5\u5177\u81ea\u52a8\u88ab\u6743\u9650\u7cfb\u7edf\u653e\u884c\u3002\u4e5f\u53ef\u901a\u8fc7tools.json\u58f0\u660e\u5f0f\u914d\u7f6e\u3002"},"8":{title:"\u914d\u7f6e\u6743\u9650\u7cfb\u7edf",desc:"\u4e09\u5c42\u51b3\u7b56: Built-in Checks(\u4e0d\u53ef\u7ed5\u8fc7) -> Rules(\u9759\u6001\u914d\u7f6e/\u52a8\u6001\u5efa\u8bae) -> Mode(\u5168\u5c40\u7b56\u7565)\u3002Deny\u89c4\u5219\u548c\u5371\u9669\u8def\u5f84\u5373\u4f7f\u5728BYPASS\u6a21\u5f0f\u4e5f\u5f3a\u5236\u751f\u6548\u3002",tabs:{"PermissionConfig.java":"import io.agentscope.core.permission.*;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class PermissionConfig {\n\n    @Bean\n    public PermissionContextState defaultPermission() {\n        return PermissionContextState.builder()\n                .mode(PermissionMode.DEFAULT)     // DEFAULT: \u672a\u547d\u4e2d\u89c4\u5219\u7684\u64cd\u4f5c\u9700\u7528\u6237\u786e\u8ba4\n                // .mode(PermissionMode.ACCEPT_EDITS)  // \u81ea\u52a8\u653e\u884c\u5de5\u4f5c\u76ee\u5f55\u5185\u6587\u4ef6\u64cd\u4f5c\n                // .mode(PermissionMode.EXPLORE)       // \u53ea\u8bfb: \u653e\u884c\u8bfb,\u62d2\u7edd\u5199\u4e0e\u547d\u4ee4\n                // .mode(PermissionMode.BYPASS)        // \u653e\u884c\u4e00\u5207(deny\u89c4\u5219\u4ecd\u751f\u6548)\n                // .mode(PermissionMode.DONT_ASK)      // \u6240\u6709ASK\u8f6cDENY(\u65e0\u4eba\u503c\u5b88)\n                .addAllowRule(\"safe_read\",\n                        new PermissionRule(\"safe_read\", null, PermissionBehavior.ALLOW, \"userSettings\"))\n                .addAskRule(\"dangerous_delete\",\n                        new PermissionRule(\"dangerous_delete\", null, PermissionBehavior.ASK, \"userSettings\"))\n                .addDenyRule(\"drop_table\",\n                        new PermissionRule(\"drop_table\", null, PermissionBehavior.DENY, \"userSettings\"))\n                .build();\n    }\n\n    @Bean\n    public HarnessAgent assistantAgent(PermissionContextState perm) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .permissionContext(perm).build();\n    }\n}"},tip:"\u7528\u6237\u786e\u8ba4\u65f6\u53ef\u63a5\u53d7getSuggestedRules(),\u89c4\u5219\u6301\u4e45\u5316\u540e\u672a\u6765\u76f8\u540c\u8c03\u7528\u81ea\u52a8\u653e\u884c\u3002\u81ea\u5b9a\u4e49Tool\u53ef\u91cd\u5199checkPermissions()\u505a\u8fd0\u884c\u65f6\u68c0\u67e5\u3002"},"9":{title:"\u6dfb\u52a0\u6280\u80fd Skill",desc:"Skill\u662fMarkdown\u6307\u4ee4\u96c6,Agent\u4e0d\u80fd\u76f4\u63a5\u8c03\u7528,\u9700\u5148\u7528Skill\u67e5\u770b\u5668\u8bfb\u53d6\u6307\u4ee4\u518d\u7528Tool\u6267\u884c\u3002\u56db\u5c42\u5408\u6210: \u5168\u5c40->\u5e02\u573a->\u5de5\u4f5c\u533a->\u7528\u6237\u9694\u79bb\u3002",tabs:{"workspace/skills/code-reviewer/SKILL.md":"---\nname: code-reviewer\ndescription: \u5f53\u7528\u6237\u9700\u8981\u4ee3\u7801\u8bc4\u5ba1\u3001\u98ce\u683c\u53cd\u9988\u6216PR\u5ba1\u6838\u65f6\u4f7f\u7528\u3002\n---\n\n# Code Reviewer\n\u6b65\u9aa4:\n1. \u5148read_file/grep_files\u6536\u96c6\u4e0a\u4e0b\u6587\n2. \u7ed9\u51fa\u6309\u6587\u4ef6/\u884c\u53f7\u7684\u5177\u4f53\u5efa\u8bae\n3. \u672b\u5c3e\u7ed9\u4e00\u4e2a1-5\u7684\u603b\u4f53\u8bc4\u5206","GitSkillRepository(\u5e26\u8ba4\u8bc1)":"import io.agentscope.extensions.skill.git.GitSkillRepository;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class SkillConfig {\n    @Bean\n    public GitSkillRepository teamSkillRepo() {\n        // \u65b9\u5f0f\u4e00: \u516c\u5f00\u4ed3\u5e93\n        // return new GitSkillRepository(\"https://github.com/org/skills.git\");\n        // \u65b9\u5f0f\u4e8c: SSH Key(\u63a8\u8350,\u514d\u5bc6\u7801)\n        // return new GitSkillRepository(\"git@github.com:org/skills.git\");\n        // \u65b9\u5f0f\u4e09: HTTPS + Token\n        String token = System.getenv(\"GITLAB_ACCESS_TOKEN\");\n        String url = \"https://gitlab.com/org/skills.git\"\n                .replace(\"https://\", \"https://oauth2:\" + token + \"@\");\n        return new GitSkillRepository(url);\n    }\n    @Bean\n    public HarnessAgent agent(GitSkillRepository repo) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).skillRepository(repo).build();\n    }\n}","pom.xml(Git)":"<dependency>\n    <groupId>io.agentscope</groupId>\n    <artifactId>agentscope-extensions-skill-git-repository</artifactId>\n    <version>2.0.0-RC1</version>\n</dependency>","NacosSkillRepository":"import io.agentscope.extensions.nacos.NacosSkillRepository;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class NacosSkillConfig {\n    @Bean\n    public NacosSkillRepository nacosSkillRepo() {\n        return new NacosSkillRepository(aiService, \"DEFAULT_GROUP\");\n        // Nacos\u53d8\u66f4\u65f6\u81ea\u52a8\u63a8\u9001,Agent\u4e0b\u4e00\u8f6e\u63a8\u7406\u7acb\u5373\u751f\u6548\n    }\n    @Bean\n    public HarnessAgent agent(NacosSkillRepository r) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).skillRepository(r).build();\n    }\n}","pom.xml(Nacos)":"<dependency>\n    <groupId>io.agentscope</groupId>\n    <artifactId>agentscope-extensions-nacos-skill</artifactId>\n    <version>2.0.0-RC1</version>\n</dependency>\n<dependency>\n    <groupId>com.alibaba.nacos</groupId>\n    <artifactId>nacos-client</artifactId>\n    <version>2.3.2</version>\n</dependency>","MysqlSkillRepository":"import io.agentscope.extensions.skill.mysql.MysqlSkillRepository;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport javax.sql.DataSource;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class MysqlSkillConfig {\n    @Bean\n    public MysqlSkillRepository mysqlSkillRepo(DataSource ds) {\n        return MysqlSkillRepository.builder(ds)\n                .databaseName(\"agentscope\").skillsTableName(\"skills\")\n                .createIfNotExist(true).writeable(true).build();\n    }\n    @Bean\n    public HarnessAgent agent(MysqlSkillRepository r) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).skillRepository(r).build();\n    }\n}","pom.xml(MySQL)":"<dependency>\n    <groupId>io.agentscope</groupId>\n    <artifactId>agentscope-extensions-skill-mysql</artifactId>\n    <version>2.0.0-RC1</version>\n</dependency>\n<dependency>\n    <groupId>com.mysql</groupId>\n    <artifactId>mysql-connector-j</artifactId>\n    <version>8.4.0</version>\n    <scope>runtime</scope>\n</dependency>","ClasspathSkillRepository":"import io.agentscope.extensions.skill.classpath.ClasspathSkillRepository;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class ClasspathSkillConfig {\n    @Bean\n    public ClasspathSkillRepository classpathSkillRepo() {\n        // \u6280\u80fd\u6587\u4ef6\u653e\u5728 src/main/resources/skills/<name>/SKILL.md\n        return new ClasspathSkillRepository(\"skills\");\n    }\n    @Bean\n    public HarnessAgent agent(ClasspathSkillRepository r) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).skillRepository(r).build();\n    }\n}"},tip:"description\u51b3\u5b9aAgent\u7528\u4e0d\u7528\u3002\u56db\u5c42\u5408\u6210: \u5168\u5c40->Git/Nacos/MySQL/Classpath\u5e02\u573a->\u5de5\u4f5c\u533a->\u7528\u6237\u9694\u79bb\u3002"},"10":{title:"\u58f0\u660e\u5b50 Agent",desc:"\u5b50Agent\u662f\u4e34\u65f6HarnessAgent\u5b9e\u4f8b\u8dd1\u81ea\u5df1\u4f1a\u8bdd\u3002\u540c\u6b65(timeout>0)\u963b\u585e\u7b49\u7ed3\u679c; \u540e\u53f0(timeout=0)\u7acb\u5373\u8fd4\u56detask_id,\u5b8c\u6210\u540esystem-reminder\u81ea\u52a8\u53cd\u5411\u901a\u77e5,\u65e0\u9700\u8f6e\u8be2\u3002",tabs:{"SubagentConfig.java":"import io.agentscope.harness.agent.HarnessAgent;\nimport io.agentscope.harness.agent.subagent.SubagentDeclaration;\nimport io.agentscope.harness.agent.subagent.WorkspaceMode;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\nimport java.util.List;\n\n@Configuration\npublic class SubagentConfig {\n    @Bean\n    public HarnessAgent orchestratorAgent() {\n        return HarnessAgent.builder()\n                .name(\"orchestrator\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .subagent(SubagentDeclaration.builder()\n                        .name(\"reviewer\")\n                        .description(\"\u4ee3\u7801\u5ba1\u67e5\u4e13\u5bb6\")\n                        .workspaceMode(WorkspaceMode.ISOLATED)\n                        .model(\"dashscope:qwen-max\").steps(8)\n                        .tools(List.of(\"read_file\", \"grep_files\"))\n                        .build())\n                .subagent(SubagentDeclaration.builder()\n                        .name(\"remote-researcher\")\n                        .description(\"\u8fdc\u7aef\u8c03\u7814\u5b50Agent\")\n                        .url(\"http://agent-task-server:8080\")\n                        .headers(Map.of(\"Authorization\", \"Bearer xxx\"))\n                        .build())\n                .build();\n    }\n}","workspace/subagents/reviewer.md":"---\ndescription: \u4ee3\u7801\u8bc4\u5ba1\u4e13\u5bb6\u3002\u5f53\u7528\u6237\u9700\u8981review PR\u65f6\u4f7f\u7528\u3002\nworkspace:\n  mode: isolated\n  model: dashscope:qwen-max\n  steps: 8\n  tools: [read_file, grep_files, glob_files]\n---\n\n\u4f60\u662f\u4e00\u4e2a\u4e13\u6ce8\u4ee3\u7801\u8bc4\u5ba1\u7684\u5b50Agent\u3002\n1. \u5148\u6536\u96c6\u4e0a\u4e0b\u6587\n2. \u7ed9\u51fa\u6309\u6587\u4ef6/\u884c\u53f7\u7684\u5177\u4f53\u5efa\u8bae\n3. \u672b\u5c3e\u7ed9\u4e00\u4e2a1-5\u7684\u603b\u4f53\u8bc4\u5206"},tip:"\u540c\u6b65(timeout_seconds>0)\u963b\u585e\u7b49\u7ed3\u679c; \u540e\u53f0(timeout_seconds=0)\u65e0\u9700\u8f6e\u8be2\u3002\u9012\u5f52\u4fdd\u62a43\u5c42\u3002userId\u81ea\u52a8\u900f\u4f20\u3002"},"11":{title:"\u542f\u7528 Plan Mode",desc:"Plan Mode\u8fdb\u5165\u53ea\u8bfb\u9636\u6bb5: \u53ea\u5141\u8bb8\u53ea\u8bfb\u5de5\u5177+plan_enter/plan_write/plan_exit/todo_write\u3002\u9000\u51fa\u65f6\u8d70HITL\u786e\u8ba4\u3002\u72b6\u6001\u968fAgentState\u6301\u4e45\u5316\u3002",tabs:{"AgentConfig.java":"import io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class AgentConfig {\n    @Bean\n    public HarnessAgent plannerAgent() {\n        return HarnessAgent.builder()\n                .name(\"planner\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .enablePlanMode()          // \u5f00\u542fPlanMode\u4e09\u4ef6\u5957\n                .enableTaskList(true)      // \u914d\u5408todo_write\u4f7f\u7528\n                .planFileDirectory(\"plans\")\n                .build();\n    }\n}","PlanController.java":"import io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.web.bind.annotation.*;\nimport reactor.core.publisher.Mono;\n\n@RestController\n@RequestMapping(\"/api/plan\")\npublic class PlanController {\n    private final HarnessAgent agent;\n    public PlanController(HarnessAgent a) { this.agent = a; }\n\n    @PostMapping(\"/enter\")\n    public Mono<String> enterPlanMode() { agent.enterPlanMode(); return Mono.just(\"OK\"); }\n\n    @PostMapping(\"/exit\")\n    public Mono<String> exitPlanMode() { agent.exitPlanMode(); return Mono.just(\"OK\"); }\n\n    @GetMapping(\"/status\")\n    public Mono<String> status() { return Mono.just(\"active: \" + agent.isPlanModeActive()); }\n}"},tip:"\u5178\u578b\u6d41\u7a0b: plan\u9636\u6bb5\u5199PLAN.md -> plan_exit -> \u6267\u884c\u9636\u6bb5\u7528todo_write\u62c6\u62105-8\u6761 -> \u9010\u6761\u63a8\u8fdb\u3002"},"12":{title:"\u81ea\u5b9a\u4e49 Middleware",desc:"\u4e94\u4e2a\u9636\u6bb5: onAgent(\u6574\u6b21reply)/onReasoning(\u63a8\u7406)/onActing(\u5de5\u5177\u6267\u884c)/onModelCall(\u6a21\u578b\u8c03\u7528)/onSystemPrompt(prompt\u53d8\u6362)\u3002Onion\u5f0f\u524d\u5165\u540e\u51fa,Transformer\u5f0f\u5de6\u5230\u53f3\u4e32\u884c\u3002",tabs:{"TimingMiddleware.java":"import io.agentscope.core.agent.Agent;\nimport io.agentscope.core.event.AgentEvent;\nimport io.agentscope.core.middleware.MiddlewareBase;\nimport io.agentscope.core.middleware.ModelCallInput;\nimport org.springframework.stereotype.Component;\nimport reactor.core.publisher.Flux;\nimport java.util.function.Function;\n\n@Component\npublic class TimingMiddleware implements MiddlewareBase {\n    @Override\n    public Flux<AgentEvent> onModelCall(Agent agent, ModelCallInput input,\n                                        Function<ModelCallInput, Flux<AgentEvent>> next) {\n        long start = System.nanoTime();\n        return next.apply(input).doFinally(sig -> {\n            long ms = (System.nanoTime() - start) / 1_000_000;\n            System.out.println(\"[timing] \" + agent.getName() + \": \" + ms + \"ms\");\n        });\n    }\n}","DynamicPromptMiddleware.java":"import io.agentscope.core.agent.Agent;\nimport io.agentscope.core.agent.RuntimeContext;\nimport io.agentscope.core.event.AgentEvent;\nimport io.agentscope.core.middleware.AgentInput;\nimport io.agentscope.core.middleware.MiddlewareBase;\nimport org.springframework.stereotype.Component;\nimport reactor.core.publisher.Flux;\nimport reactor.core.publisher.Mono;\nimport java.time.Instant;\nimport java.util.function.Function;\n\n@Component\npublic class DynamicPromptMiddleware implements MiddlewareBase {\n    @Override\n    public Flux<AgentEvent> onAgent(Agent agent, AgentInput input,\n                                    Function<AgentInput, Flux<AgentEvent>> next) {\n        RuntimeContext rc = agent.getRuntimeContext();\n        if (rc != null) System.out.printf(\"[req] user=%s%n\", rc.getUserId());\n        return next.apply(input);\n    }\n\n    @Override\n    public Mono<String> onSystemPrompt(Agent agent, String currentPrompt) {\n        return Mono.just(currentPrompt + \"\\n\\n## Current Time\\n\" + Instant.now());\n    }\n}","AgentConfig.java(\u6ce8\u5165)":"import io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\nimport java.util.List;\n\n@Configuration\npublic class AgentConfig {\n    @Bean\n    public HarnessAgent assistantAgent(TimingMiddleware timing, DynamicPromptMiddleware prompt) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .middlewares(List.of(timing, prompt)).build();\n    }\n}"},tip:"Onion\u6267\u884c\u987a\u5e8f: mw1\u524d->mw2\u524d->\u5185\u90e8->mw2\u540e->mw1\u540e\u3002Transformer(onSystemPrompt): \u5de6\u5230\u53f3\u4e32\u884c\u63a5\u529b\u3002"},"13":{title:"SSE \u6d41\u5f0f\u63a5\u53e3",desc:"streamEvents()\u8fd4\u56deFlux<AgentEvent>,\u6bcf\u4e2a\u4e8b\u4ef6\u662f\u7c7b\u578b\u5316\u7684\u589e\u91cf\u8fdb\u5ea6\u3002\u6309event.getType()\u5206\u53d1: TEXT_BLOCK_DELTA(\u6587\u672c)/TOOL_CALL_START(\u5de5\u5177)/AGENT_END(\u5b8c\u6210)\u3002",tabs:{"ChatController.java":"import io.agentscope.core.agent.RuntimeContext;\nimport io.agentscope.core.event.*;\nimport io.agentscope.core.message.UserMessage;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.codec.ServerSentEvent;\nimport org.springframework.web.bind.annotation.*;\nimport reactor.core.publisher.Flux;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport java.util.*;\n\n@RestController\n@RequestMapping(\"/api/chat\")\npublic class ChatController {\n    private final HarnessAgent agent;\n    private final ObjectMapper mapper;\n    public ChatController(HarnessAgent a, ObjectMapper m) { this.agent = a; this.mapper = m; }\n\n    @GetMapping(value=\"/stream\", produces=MediaType.TEXT_EVENT_STREAM_VALUE)\n    public Flux<ServerSentEvent<String>> stream(@RequestParam String message,\n                                                @RequestParam(defaultValue=\"default\") String sessionId) {\n        RuntimeContext ctx = RuntimeContext.builder().sessionId(sessionId).userId(\"user\").build();\n        return agent.streamEvents(new UserMessage(message), ctx)\n                .map(event -> {\n                    Map<String, Object> p = new LinkedHashMap<>();\n                    p.put(\"type\", event.getType().name());\n                    if (event instanceof TextBlockDeltaEvent d) p.put(\"delta\", d.getDelta());\n                    else if (event instanceof ToolCallStartEvent t) p.put(\"tool\", t.getToolCallName());\n                    else if (event instanceof AgentEndEvent) p.put(\"done\", true);\n                    try { return ServerSentEvent.<String>builder()\n                            .data(mapper.writeValueAsString(p)).build();\n                    } catch (Exception e) { return ServerSentEvent.<String>builder().data(\"{}\").build(); }\n                });\n    }\n}"},tip:"\u4e00\u6b21call\u4ea7\u51fa\u7684\u6240\u6709\u4e8b\u4ef6\u6700\u7ec8\u6c47\u805a\u6210\u6070\u597d\u4e00\u6761assistant Msg\u3002\u524d\u7aef\u53ef\u6309replyId/blockId/toolCallId\u5206\u7ec4\u8fd8\u539f\u5b8c\u6574\u6d88\u606f\u3002"},"14":{title:"HITL \u4ea4\u4e92\u63a5\u53e3",desc:"\u6743\u9650\u7cfb\u7edf\u8fd4\u56deASK\u65f6Agent\u53d1\u51faRequireUserConfirmEvent\u6682\u505c\u3002\u524d\u7aef\u5c55\u793a\u786e\u8ba4\u754c\u9762,\u7528\u6237\u786e\u8ba4/\u62d2\u7edd\u540e\u901a\u8fc7\u4e0b\u4e00\u6b21call()\u4f20\u56deConfirmResult\u6062\u590d\u6267\u884c\u3002",tabs:{"HitlController.java":"import io.agentscope.core.agent.RuntimeContext;\nimport io.agentscope.core.event.ConfirmResult;\nimport io.agentscope.core.event.RequireUserConfirmEvent;\nimport io.agentscope.core.event.TextBlockDeltaEvent;\nimport io.agentscope.core.message.Msg;\nimport io.agentscope.core.message.UserMessage;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.codec.ServerSentEvent;\nimport org.springframework.web.bind.annotation.*;\nimport reactor.core.publisher.Flux;\nimport reactor.core.publisher.Mono;\nimport java.util.*;\n\n@RestController\n@RequestMapping(\"/api/chat\")\npublic class HitlController {\n    private final HarnessAgent agent;\n    public HitlController(HarnessAgent a) { this.agent = a; }\n\n    @GetMapping(value=\"/interactive\", produces=MediaType.TEXT_EVENT_STREAM_VALUE)\n    public Flux<ServerSentEvent<String>> interactive(@RequestParam String message,\n                                                     @RequestParam String sessionId) {\n        RuntimeContext ctx = RuntimeContext.builder().sessionId(sessionId).userId(\"user\").build();\n        return agent.streamEvents(new UserMessage(message), ctx)\n                .flatMap(event -> {\n                    if (event instanceof RequireUserConfirmEvent confirm) {\n                        Map<String, Object> p = new LinkedHashMap<>();\n                        p.put(\"type\", \"REQUIRE_CONFIRM\");\n                        p.put(\"replyId\", confirm.getReplyId());\n                        p.put(\"toolCalls\", confirm.getToolCalls().stream()\n                                .map(tc -> Map.of(\"name\", tc.getName()))\n                                .toList());\n                        try { return Flux.just(ServerSentEvent.<String>builder()\n                                .data(new com.fasterxml.jackson.databind.ObjectMapper()\n                                        .writeValueAsString(p)).build());\n                        } catch (Exception e) { return Flux.empty(); }\n                    }\n                    Map<String, Object> p = new LinkedHashMap<>();\n                    p.put(\"type\", event.getType().name());\n                    if (event instanceof TextBlockDeltaEvent d) p.put(\"delta\", d.getDelta());\n                    try { return Flux.just(ServerSentEvent.<String>builder()\n                            .data(new com.fasterxml.jackson.databind.ObjectMapper()\n                                    .writeValueAsString(p)).build());\n                    } catch (Exception e) { return Flux.empty(); }\n                });\n    }\n\n    @PostMapping(\"/confirm\")\n    public Mono<Map<String, String>> confirm(@RequestParam String sessionId,\n                                             @RequestBody List<ConfirmResult> results) {\n        RuntimeContext ctx = RuntimeContext.builder().sessionId(sessionId).userId(\"user\").build();\n        UserMessage resumeMsg = UserMessage.builder()\n                .metadata(Map.of(Msg.METADATA_CONFIRM_RESULTS, results)).build();\n        return agent.call(List.of(resumeMsg), ctx)\n                .map(msg -> Map.of(\"reply\", msg.getTextContent()));\n    }\n}"},tip:"ConfirmResult\u6784\u9020: new ConfirmResult(confirmed, toolCall, rules)\u3002\u63a5\u53d7suggestedRules\u53ef\u8ba9\u672a\u6765\u76f8\u540c\u8c03\u7528\u81ea\u52a8\u653e\u884c\u3002"},"15":{title:"\u63a5\u5165 AG-UI \u534f\u8bae",desc:"Spring Boot Starter\u81ea\u52a8\u6ce8\u518cSSE\u7aef\u70b9(/agui/run)\u3002AguiAgentRegistryCustomizer\u56de\u8c03\u6ce8\u518cAgent\u3002\u524d\u7aefAG-UI SDK\u76f4\u63a5\u6d88\u8d39\u4e8b\u4ef6\u6d41\u3002",tabs:{"pom.xml":"<dependency>\n    <groupId>io.agentscope</groupId>\n    <artifactId>agentscope-agui-spring-boot-starter</artifactId>\n    <version>2.0.0-RC1</version>\n</dependency>","application.yml":"agentscope:\n  agui:\n    path-prefix: /agui\n    cors-enabled: true\n    server-side-memory: true\n    default-agent-id: default\n    enable-reasoning: true","AgentConfig.java":"import io.agentscope.agui.spring.AguiAgentRegistryCustomizer;\nimport io.agentscope.agui.spring.AguiAgentRegistry;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class AgentConfig implements AguiAgentRegistryCustomizer {\n    @Override\n    public void customize(AguiAgentRegistry registry) {\n        HarnessAgent agent = HarnessAgent.builder()\n                .name(\"default\").sysPrompt(\"\u4f60\u662f\u4e00\u4e2a\u6709\u5e2e\u52a9\u7684\u52a9\u624b\u3002\")\n                .model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).build();\n        registry.register(\"default\", agent);\n    }\n}"},tip:"AG-UI\u7aef\u70b9\u9ed8\u8ba4/agui/run\u3002\u652f\u6301\u6ce8\u518c\u591a\u4e2aAgent,\u7531agent-id\u53c2\u6570\u8def\u7531\u3002"},"16":{title:"\u7ed3\u6784\u5316\u8f93\u51fa",desc:"\u6846\u67b6\u57fa\u4e8e\u76ee\u6807Class\u5408\u6210\u5f3a\u5236\u7ed3\u6784\u5316\u7684\u5de5\u5177\u8c03\u7528,\u6821\u9a8c\u5e76\u4fee\u590d\u6a21\u578b\u8f93\u51fa\u3002\u7ed3\u679c\u6302\u5230Msg.metadata\u7684structured_output\u5b57\u6bb5\u3002",tabs:{"StructuredOutputController.java":"import io.agentscope.core.agent.RuntimeContext;\nimport io.agentscope.core.message.Msg;\nimport io.agentscope.core.message.UserMessage;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.web.bind.annotation.*;\nimport reactor.core.publisher.Mono;\nimport java.util.List;\n\n@RestController\n@RequestMapping(\"/api/chat\")\npublic class StructuredOutputController {\n    private final HarnessAgent agent;\n    public StructuredOutputController(HarnessAgent a) { this.agent = a; }\n\n    /** \u7ed3\u6784\u5316\u8f93\u51fa: \u6a21\u578b\u7ed3\u679c\u81ea\u52a8\u7ed1\u5b9a\u5230POJO */\n    @PostMapping(\"/weather\")\n    public Mono<WeatherInfo> getWeather(@RequestBody String message, @RequestParam String sessionId) {\n        RuntimeContext ctx = RuntimeContext.builder().sessionId(sessionId).userId(\"user\").build();\n        // call(msgs, WeatherInfo.class, ctx): \u7b2c\u4e8c\u4e2a\u53c2\u6570\u6307\u5b9a\u76ee\u6807POJO\u7c7b\u578b\n        return agent.call(List.of(new UserMessage(message)), WeatherInfo.class, ctx)\n                .map(msg -> msg.getStructuredData(WeatherInfo.class));\n    }\n\n    public record WeatherInfo(String city, double temperature, String unit) {}\n}"},tip:"\u4e0d\u9700\u8981\u989d\u5916prompt\u5de5\u7a0b,\u6846\u67b6\u81ea\u52a8\u5904\u7406\u3002POJO\u5b57\u6bb5\u5373\u4e3a\u6a21\u578b\u5fc5\u987b\u8f93\u51fa\u7684\u7ed3\u6784\u3002"},"17":{title:"\u63a5\u5165 Studio + OTel",desc:"OtelTracingMiddleware\u5728onAgent/onModelCall/onActing\u4e09\u5904\u6253\u70b9,\u6309OpenTelemetry GenAI\u8bed\u4e49\u89c4\u8303\u751f\u6210span\u6811\u3002\u672a\u914d\u7f6eOTel SDK\u65f6\u96f6\u5f00\u9500\u3002",tabs:{"ObservabilityConfig.java":"import io.agentscope.core.tracing.OtelTracingMiddleware;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\nimport java.util.List;\n\n@Configuration\npublic class ObservabilityConfig {\n    @Bean\n    public OtelTracingMiddleware tracingMiddleware() {\n        return new OtelTracingMiddleware();\n        // \u81ea\u52a8\u5728\u4e09\u4e2a\u4f4d\u7f6e\u6253span:\n        //   invoke_agent: \u5305\u88f9\u6574\u6b21reply\n        //   chat: \u5305\u88f9\u6bcf\u6b21\u6a21\u578b\u8c03\u7528\n        //   execute_tool: \u5305\u88f9\u6bcf\u6b21\u5de5\u5177\u6267\u884c\n    }\n    @Bean\n    public HarnessAgent assistantAgent(OtelTracingMiddleware tracing) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .middlewares(List.of(tracing)).build();\n    }\n}"},tip:"\u914d\u5408AgentScope Studio\u83b7\u5f97\u53ef\u89c6\u5316\u8ffd\u8e2a\u9762\u677f\u3002\u5148\u521d\u59cb\u5316OTel SDK(OTLP exporter + SdkTracerProvider)\u3002"},"18":{title:"Session \u6362 Redis",desc:"RedisSession\u66ff\u6362\u9ed8\u8ba4WorkspaceSession\u3002AgentState\u5728call\u7ed3\u675f\u65f6\u6574\u4f53\u5199\u5165Redis,\u4e0b\u6b21\u540csessionId\u4eceRedis\u62c9\u56de\u3002\u652f\u6301\u591a\u526f\u672c\u5171\u4eab\u3002",tabs:{"RedisSessionConfig.java":"import io.agentscope.extensions.session.redis.RedisSession;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport io.lettuce.core.RedisClient;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class RedisSessionConfig {\n    @Bean\n    public RedisClient redisClient() {\n        return RedisClient.create(\"redis://redis.prod:6379\");\n    }\n\n    @Bean\n    public RedisSession redisSession(RedisClient client) {\n        return RedisSession.builder()\n                .lettuceClient(client)  // \u652f\u6301Jedis/Lettuce/Redisson\n                .build();\n    }\n\n    @Bean\n    public HarnessAgent assistantAgent(RedisSession session) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .session(session)  // \u66ff\u6362\u9ed8\u8ba4WorkspaceSession,AgentState\u5b58Redis\n                .build();\n    }\n}"},tip:"WorkspaceSession\u4ec5\u9002\u5408\u5355\u673a\u3002Sandbox/Remote FS\u4f46\u6ca1\u6362Session -> build()\u629bIllegalStateException\u3002"},"19":{title:"\u6587\u4ef6\u7cfb\u7edf\u6362\u8fdc\u7aef",desc:"\u4e24\u5c42\u8bfb: \u5148\u95ee\u8fdc\u7aefKV\u6709\u6ca1\u6709 -> \u6ca1\u6709\u8bfb\u672c\u5730\u78c1\u76d8\u6a21\u677f\u3002\u5199\u5165\u6c38\u8fdc\u8d70\u8fdc\u7aef\u3002IsolationScope\u6309userId\u5206\u547d\u540d\u7a7a\u95f4\u3002",tabs:{"RemoteFsConfig.java":"import io.agentscope.extensions.session.redis.RedisSession;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport io.agentscope.harness.agent.filesystem.IsolationScope;\nimport io.agentscope.harness.agent.filesystem.RemoteFilesystemSpec;\nimport io.lettuce.core.RedisClient;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class RemoteFsConfig {\n    @Bean\n    public HarnessAgent assistantAgent() {\n        RedisClient rc = RedisClient.create(\"redis://redis.prod:6379\");\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .filesystem(new RemoteFilesystemSpec(redisStore)\n                        .isolationScope(IsolationScope.USER))\n                .session(RedisSession.builder().lettuceClient(rc).build())\n                .build();\n    }\n}"},tip:"\u56e2\u961f\u7ea6\u5b9a\u6587\u4ef6\u7528git\u540c\u6b65\u5230\u672c\u5730\u78c1\u76d8\u4f5c\u6a21\u677f; \u8fd0\u884c\u65f6\u4ea7\u7269\u8ba9KV\u81ea\u5df1\u957f\u3002Remote FS + Session\u5fc5\u987b\u90fd\u662f\u5206\u5e03\u5f0f\u7684\u3002"},"20":{title:"\u5f00\u542f\u6c99\u7bb1\u9694\u79bb",desc:"DockerFilesystemSpec\u542f\u52a8\u6c99\u7bb1\u5bb9\u5668,\u9759\u6001\u8d44\u4ea7hydrate\u8fdb\u53bb,\u8fd0\u884c\u65f6\u4ea7\u7269\u843d\u5728\u6c99\u7bb1\u5185\u3002\u540csessionId\u4e0b\u6b21call\u8fde\u540c\u526f\u4f5c\u7528\u4e00\u8d77\u6062\u590d\u3002",tabs:{"SandboxConfig.java":"import io.agentscope.extensions.session.redis.RedisSession;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport io.agentscope.harness.agent.filesystem.DockerFilesystemSpec;\nimport io.agentscope.harness.agent.filesystem.IsolationScope;\nimport io.lettuce.core.RedisClient;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class SandboxConfig {\n    @Bean\n    public HarnessAgent assistantAgent() {\n        RedisClient rc = RedisClient.create(\"redis://redis.prod:6379\");\n        return HarnessAgent.builder().name(\"sandbox-agent\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .filesystem(new DockerFilesystemSpec()\n                        .image(\"ubuntu:24.04\")\n                        .isolationScope(IsolationScope.SESSION))\n                .session(RedisSession.builder().lettuceClient(rc).build())\n                .build();\n    }\n}"},tip:"\u4e5f\u652f\u6301K8s/E2B/AgentRun\u6c99\u7bb1\u3002\u6c99\u7bb1\u5feb\u7167\u8de8\u8c03\u7528\u6062\u590d,\u6eda\u52a8\u53d1\u5e03\u4e0d\u4e22\u72b6\u6001\u3002\u5bbf\u4e3b\u53ea\u4fdd\u7559\u5de5\u4f5c\u533a\u79cd\u5b50\u3002"},"21":{title:"\u591a\u79df\u6237\u9694\u79bb",desc:"RuntimeContext.userId\u662f\u5207\u591a\u7528\u6237\u7684\u94a5\u5319: \u51b3\u5b9a\u6587\u4ef6\u547d\u540d\u7a7a\u95f4\u3001Session\u6309SessionKey\u5206\u6876\u3002IsolationScope\u63a7\u5236\u9694\u79bb\u7c92\u5ea6\u3002",tabs:{"MultiTenantController.java":"import io.agentscope.core.agent.RuntimeContext;\nimport io.agentscope.core.message.Msg;\nimport io.agentscope.core.message.UserMessage;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.web.bind.annotation.*;\nimport reactor.core.publisher.Mono;\nimport java.util.List;\nimport java.util.Map;\n\n@RestController\n@RequestMapping(\"/api/chat\")\npublic class MultiTenantController {\n    private final HarnessAgent agent;\n    public MultiTenantController(HarnessAgent a) { this.agent = a; }\n\n    @PostMapping(\"/send\")\n    public Mono<Map<String, String>> chat(\n            @RequestBody String message,\n            @RequestParam String sessionId,\n            @RequestHeader(\"X-User-Id\") String userId) {  // \u4ece\u8bf7\u6c42\u5934\u83b7\u53d6\u7528\u6237ID\n        RuntimeContext ctx = RuntimeContext.builder()\n                .sessionId(sessionId).userId(userId).build();\n        return agent.call(List.of(new UserMessage(message)), ctx)\n                .map(msg -> Map.of(\"reply\", msg.getTextContent()));\n    }\n}"},tip:"sessionId\u51b3\u5b9a\u5bf9\u8bdd,userId\u51b3\u5b9a\u6587\u4ef6\u547d\u540d\u7a7a\u95f4\u3002\u751f\u4ea7\u505aAgentState\u7ea7\u9694\u79bb\u9996\u9009\u628auserId\u7f16\u7801\u8fdbSessionKey\u3002"},"22":{title:"\u6743\u9650\u52a0\u56fa",desc:"DONT_ASK\u6a21\u5f0f\u628a\u6240\u6709ASK\u8f6cDENY,\u53ea\u6709addAllowRule\u663e\u5f0f\u653e\u884c\u7684\u547d\u4ee4\u4f1a\u6267\u884c\u3002Deny\u89c4\u5219\u4e0d\u53ef\u7ed5\u8fc7\u3002",tabs:{"CiPermissionConfig.java":"import io.agentscope.core.permission.*;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class CiPermissionConfig {\n    @Bean\n    public HarnessAgent ciAgent() {\n        PermissionContextState perm = PermissionContextState.builder()\n                .mode(PermissionMode.DONT_ASK)  // \u6240\u6709ASK\u8f6cDENY\n                .addAllowRule(\"deploy\",\n                        new PermissionRule(\"deploy\", \"staging\",\n                                PermissionBehavior.ALLOW, \"project\"))\n                .addAllowRule(\"git_commit\",\n                        new PermissionRule(\"git_commit\", null,\n                                PermissionBehavior.ALLOW, \"project\"))\n                .addDenyRule(\"drop_table\",\n                        new PermissionRule(\"drop_table\", null,\n                                PermissionBehavior.DENY, \"project\"))\n                .build();\n        return HarnessAgent.builder().name(\"ci-agent\").model(\"dashscope:qwen-plus\")\n                .sysPrompt(\"CI\u81ea\u52a8\u5316Agent\").workspace(Paths.get(\".agentscope/workspace\"))\n                .permissionContext(perm).build();\n    }\n}"},tip:"\u5371\u9669\u8def\u5f84\u4fdd\u62a4(.bashrc/.ssh/.env/.aws/\u7b49)\u81ea\u52a8\u751f\u6548,\u5373\u4f7fBYPASS\u4e5f\u5f3a\u5236ASK\u3002"},"23":{title:"\u53ef\u89c2\u6d4b\u6027",desc:"OtelTracingMiddleware\u6309OpenTelemetry GenAI\u8bed\u4e49\u89c4\u8303\u751f\u6210\u5d4c\u5957span\u6811: invoke_agent -> chat -> execute_tool\u3002\u672a\u914d\u7f6eSDK\u65f6\u77ed\u8def,\u96f6\u5f00\u9500\u3002",tabs:{"ObservabilityConfig.java":"import io.agentscope.core.tracing.OtelTracingMiddleware;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\nimport java.util.List;\n\n@Configuration\npublic class ObservabilityConfig {\n    @Bean\n    public OtelTracingMiddleware tracingMiddleware() {\n        return new OtelTracingMiddleware();\n    }\n    @Bean\n    public HarnessAgent assistantAgent(OtelTracingMiddleware tracing) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .middlewares(List.of(tracing)).build();\n    }\n}"},tip:"\u914d\u5408AgentScope Studio\u53ef\u89c6\u5316\u3002\u9700\u8981\u5148\u521d\u59cb\u5316OTel SDK(OTLP exporter + SdkTracerProvider)\u3002"},"24":{title:"\u6eda\u52a8\u53d1\u5e03",desc:"shutdownManager\u5728\u8fdb\u7a0b\u9000\u51fa\u65f6\u81ea\u52a8\u8c03\u7528session.save()\u3002\u65b0Pod\u540csessionId\u4eceSession\u62c9\u56de\u5b8c\u6574AgentState\u3002Session\u5728call\u7ed3\u675f\u65f6\u6574\u4f53\u5199\u5165(\u975e\u9010\u6761)\u3002",tabs:{"application.yml":"server:\n  shutdown: graceful\nspring:\n  lifecycle:\n    timeout-per-shutdown-phase: 30s","\u8bf4\u660e":"// \u6eda\u52a8\u53d1\u5e03\u662f\u67b6\u6784\u7ea7\u80fd\u529b,\u4e0d\u9700\u8981\u989d\u5916\u4ee3\u7801\n// \u524d\u63d0: @Bean\u914d\u4e86RedisSession\n//\n// \u81ea\u52a8\u6d41\u7a0b:\n// 1. \u65e7Pod\u6536\u5230SIGTERM\n// 2. shutdownManager -> session.save()\u4fdd\u5b58AgentState\n// 3. Spring Boot\u7b49\u5f85\u5728\u9014\u8bf7\u6c42\u5b8c\u6210(graceful shutdown)\n// 4. \u65b0Pod\u542f\u52a8,\u540csessionId -> \u4eceRedis\u62c9\u56deAgentState\n// 5. \u7528\u6237\u5bf9\u8bdd\u96f6\u4e2d\u65ad\n//\n// shutdownManager\u662fReActAgent\u81ea\u5e26\u7684,\u81ea\u52a8\u7ed1\u5b9a"},tip:"Session\u5728call\u7ed3\u675f/shutdown\u65f6\u6574\u4f53\u5199\u5165,\u975e\u9010\u6761,\u5bf9Redis\u541e\u5410\u538b\u529b\u4f4e\u3002"},"25":{title:"\u6545\u969c\u8f6c\u79fb",desc:"\u53ea\u8981Session\u540e\u7aef\u662f\u5206\u5e03\u5f0f\u7684(Redis/MySQL),\u540csessionId\u7684call()\u81ea\u52a8\u4eceSession\u52a0\u8f7d\u4e4b\u524d\u7684AgentState\u3002\u8fd9\u662fSession\u62bd\u8c61\u7684\u5185\u7f6e\u80fd\u529b\u3002",tabs:{"\u8bf4\u660e":"// \u6545\u969c\u8f6c\u79fb\u662f\u67b6\u6784\u7ea7\u80fd\u529b,\u4e0d\u9700\u8981\u989d\u5916\u4ee3\u7801\n// \u53ea\u9700\u786e\u4fdd:\n//   1. Session\u540e\u7aef\u662f\u5206\u5e03\u5f0f\u7684(Redis/MySQL) - \u53c2\u8003Step 18\n//   2. \u5de5\u4f5c\u533a\u6587\u4ef6\u7cfb\u7edf\u662f\u5171\u4eab\u7684(Remote/Sandbox) - \u53c2\u8003Step 19/20\n//\n// \u9a8c\u8bc1\u6b65\u9aa4:\n// 1. \u8282\u70b9A\u53d1\u8d77\u5bf9\u8bdd\n// 2. \u6740\u6389\u8282\u70b9A\n// 3. \u8282\u70b9B\u7528\u76f8\u540csessionId\u7ee7\u7eed\u5bf9\u8bdd\n// 4. Agent\u4eceRedis\u6062\u590d\u5b8c\u6574AgentState,\u5bf9\u8bdd\u7ee7\u7eed\n//\n// \u4ee3\u7801\u540cStep 18(RedisSession) + Step 19/20(RemoteFilesystem/Sandbox)\n// \u65e0\u9700\u989d\u5916\u6539\u52a8"},tip:"\u8de8\u573a\u666f\u63a5\u7eed: Web UI\u804a\u5230\u4e00\u534a\u5207CLI - sessionId\u4e00\u81f4\u5373\u53ef\u3002"},"26":{title:"Skill \u81ea\u5b66\u4e60\u95ed\u73af",desc:"\u4e09\u9636\u6bb5: \u2460enableSkillManageTool\u8ba9Agent\u8d77\u8349\u548c\u7f16\u8f91Skill; \u2461enableSkillPromotionGate\u52a0\u5ba1\u6838\u95f8\u95e8+\u7070\u5ea6; \u2462enableSkillCurator\u540e\u53f0\u5468\u671f\u6574\u7406/\u5f52\u6863\u3002",tabs:{"SkillLearningConfig.java":"import io.agentscope.harness.agent.HarnessAgent;\nimport io.agentscope.harness.agent.skill.SkillCuratorConfig;\nimport io.agentscope.harness.agent.skill.SkillManageConfig;\nimport io.agentscope.harness.agent.skill.gate.LocalApprovalGate;\nimport io.agentscope.harness.agent.skill.filter.CanaryFilter;\nimport io.agentscope.harness.agent.skill.filter.CompositeFilter;\nimport io.agentscope.harness.agent.skill.filter.EnvironmentFilter;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\nimport java.util.List;\n\n@Configuration\npublic class SkillLearningConfig {\n    @Bean\n    public HarnessAgent assistantAgent() {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\"))\n                .enableSkillManageTool(SkillManageConfig.defaults())\n                .enableSkillPromotionGate(\n                        new LocalApprovalGate(LocalApprovalGate.defaultPrompter()),\n                        new CompositeFilter(List.of(\n                                new EnvironmentFilter(\"prod\", null),\n                                new CanaryFilter(0.10, null))))\n                .environment(\"prod\")\n                .enableSkillCurator(SkillCuratorConfig.builder()\n                        .intervalHours(7*24).minIdleHours(2)\n                        .staleAfterDays(30).archiveAfterDays(90).build())\n                .build();\n    }\n}"},tip:"\u6309\u987a\u5e8f\u542f\u7528: \u5148SkillManageTool,\u518dPromotionGate,\u6700\u540eCurator\u3002"},"27":{title:"\u63a5\u5165 A2A \u534f\u8bae",desc:"A2A (Agent-to-Agent) \u662f\u6807\u51c6\u5316\u8de8\u6846\u67b6Agent\u4e92\u64cd\u4f5c\u534f\u8bae\u3002\u4e0eSubagent\u4e92\u8865: Subagent\u7ba1\u6846\u67b6\u5185\u7f16\u6392, A2A\u7ba1\u8de8\u6846\u67b6\u4e92\u8c03\u3002",tabs:{"pom.xml":"<dependency>\n    <groupId>io.agentscope</groupId>\n    <artifactId>agentscope-extensions-protocol-a2a</artifactId>\n    <version>2.0.0-RC1</version>\n</dependency>","\u7ed3\u5408Subagent":"// A2A\u4e0eSubagent\u7ed3\u5408:\n// \u672c\u5730\u5b50Agent: agent_spawn / agent_send\n// \u8fdc\u7a0b\u5b50Agent(AgentProtocol): SubagentDeclaration.url()\n// A2A: \u8de8\u6846\u67b6\u6807\u51c6\u5316\u4e92\u64cd\u4f5c\n\n// .subagent(SubagentDeclaration.builder()\n//     .name(\"remote-researcher\")\n//     .url(\"http://other-system:8080\")  // A2A\u517c\u5bb9\u7aef\u70b9\n//     .build())"},tip:"A2A\u63d0\u4f9b\u8de8\u6846\u67b6\u4e92\u64cd\u4f5c, Subagent\u63d0\u4f9b\u6846\u67b6\u5185\u7f16\u6392\u3002\u4e24\u8005\u53ef\u4ee5\u5171\u5b58\u3002"},"28":{title:"\u57fa\u7840\u8bbe\u65bd\u96c6\u6210",desc:"\u591a\u6570\u6269\u5c55\u6709Spring Boot Starter\u7248\u672c\u3002Higress\u505aAI\u7f51\u5173/\u9650\u6d41/\u9274\u6743; Nacos\u505a\u914d\u7f6e+Skill\u4ed3\u5e93; RocketMQ\u505a\u4e8b\u4ef6\u9a71\u52a8; Scheduler\u505a\u5b9a\u65f6\u8c03\u5ea6\u3002",tabs:{"NacosSkill @Bean":"import io.agentscope.extensions.nacos.NacosSkillRepository;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class NacosSkillConfig {\n    @Bean\n    public NacosSkillRepository nacosSkillRepo() {\n        return new NacosSkillRepository(aiService, \"DEFAULT_GROUP\");\n    }\n    @Bean\n    public HarnessAgent agent(NacosSkillRepository r) {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).skillRepository(r).build();\n    }\n}","\u5e38\u7528Starter":"<!-- Higress AI\u7f51\u5173: \u9650\u6d41/\u9274\u6743/\u591a\u6a21\u578b\u8def\u7531 -->\n<dependency>\n  <groupId>io.agentscope</groupId>\n  <artifactId>agentscope-extensions-infrastructure-higress</artifactId>\n  <version>2.0.0-RC1</version>\n</dependency>\n\n<!-- Nacos Skill\u4ed3\u5e93+\u914d\u7f6e\u4e2d\u5fc3 -->\n<dependency>\n  <groupId>io.agentscope</groupId>\n  <artifactId>agentscope-extensions-nacos-skill</artifactId>\n  <version>2.0.0-RC1</version>\n</dependency>\n\n<!-- Scheduler(Quartz/XXL-Job): \u5b9a\u65f6\u62a5\u544a/\u5de1\u68c0/\u8fd0\u7ef4 -->\n<dependency>\n  <groupId>io.agentscope</groupId>\n  <artifactId>agentscope-extensions-infrastructure-scheduler</artifactId>\n  <version>2.0.0-RC1</version>\n</dependency>"},tip:"\u7edd\u5927\u591a\u6570\u6269\u5c55\u90fd\u6709agentscope-spring-boot-starter-*\u4e00\u952e\u63a5\u5165\u7248\u672c\u3002"},"29":{title:"RAG \u77e5\u8bc6\u5e93",desc:"Knowledge\u63a5\u53e3\u7edf\u4e00,\u5207\u6362\u540e\u7aef\u53ea\u9700\u6362\u5b9e\u73b0\u7c7b\u3002knowledge/KNOWLEDGE.md\u5168\u6587\u6ce8\u5165prompt,\u5176\u4ed6\u6587\u4ef6\u53ea\u5217\u8def\u5f84\u6e05\u5355\u8ba9Agent\u6309\u9700read_file\u3002",tabs:{"RagConfig.java":"import io.agentscope.extensions.rag.dify.DifyKnowledge;\nimport io.agentscope.harness.agent.HarnessAgent;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport java.nio.file.Paths;\n\n@Configuration\npublic class RagConfig {\n    @Bean\n    public DifyKnowledge difyKnowledge() {\n        return DifyKnowledge.builder()\n                .apiKey(System.getenv(\"DIFY_API_KEY\"))\n                .baseUrl(\"https://api.dify.ai/v1\")\n                .datasetId(\"your-dataset-id\").build();\n    }\n    @Bean\n    public HarnessAgent assistantAgent() {\n        return HarnessAgent.builder().name(\"assistant\").model(\"dashscope:qwen-plus\")\n                .workspace(Paths.get(\".agentscope/workspace\")).build();\n    }\n}"},tip:"Knowledge\u63a5\u53e3\u7edf\u4e00,\u5207\u6362\u540e\u7aef\u53ea\u9700\u6362@Bean\u5b9e\u73b0\u3002\u652f\u6301: Simple/\u767e\u70bc/Dify/RAGFlow/HayStack\u3002"},"30":{title:"tools.json \u58f0\u660e\u5f0f\u914d\u7f6e",desc:"tools.json\u5728build()\u65f6\u4e00\u6b21\u6027\u8bfb\u53d6: \u6ce8\u518cMCP\u5ba2\u6237\u7aef\u3001\u5e94\u7528allow/deny\u8fc7\u6ee4\u3002\u652f\u6301${ENV_VAR}\u73af\u5883\u53d8\u91cf\u66ff\u6362\u3002\u4e5f\u53ef\u901a\u8fc7builder.toolsConfig()\u7f16\u7a0b\u5f0f\u6ce8\u5165\u3002",tabs:{"workspace/tools.json":"{\n  \"allow\": [\"read_file\", \"grep_files\", \"execute\", \"memory_search\",\n            \"agent_spawn\", \"get_current_time\", \"web_search\"],\n  \"deny\": [\"write_file\"],\n  \"mcpServers\": {\n    \"amap\": {\n      \"transport\": \"streamableHttp\",\n      \"url\": \"https://mcp.amap.com/mcp?key=${AMAP_API_KEY}\"\n    },\n    \"filesystem\": {\n      \"transport\": \"stdio\",\n      \"command\": \"mcp-server-filesystem\",\n      \"args\": [\"--root\", \"/project\"],\n      \"env\": { \"PYTHONUNBUFFERED\": \"1\" }\n    },\n    \"search\": {\n      \"transport\": \"sse\",\n      \"url\": \"https://api.search.com/mcp/sse\"\n    }\n  }\n}","\u6ce8\u610f\u4e8b\u9879":"// allow/deny\u5728\u6240\u6709\u5de5\u5177\u6ce8\u518c\u5b8c\u4e4b\u540e\u624d\u5e94\u7528\n// \u6240\u4ee5\u4e5f\u4f1a\u8fc7\u6ee4\u6389Harness\u7684\u5185\u7f6e\u5de5\u5177!\n// \u7528allow\u767d\u540d\u5355\u65f6\u52a1\u5fc5\u628a\u8981\u4fdd\u7559\u7684\u5185\u7f6e\u5de5\u5177\u4e00\u5e76\u5217\u51fa:\n//   read_file, grep_files, execute, memory_search,\n//   agent_spawn, agent_send, agent_list,\n//   plan_enter, plan_write, plan_exit, todo_write\n//\n// \u4e0d\u60f3\u7528\u6587\u4ef6? \u7f16\u7a0b\u5f0f:\n// builder.toolsConfig(ToolsConfig.builder()...)\n// \u5b8c\u5168\u5173\u6389: builder.disableToolsConfig()"},tip:"allow\u4f1a\u5f71\u54cd\u5185\u7f6e\u5de5\u5177\u3002\u7528\u767d\u540d\u5355\u65f6\u52a1\u5fc5\u628aread_file/memory_search/agent_spawn\u7b49\u5185\u7f6e\u5de5\u5177\u5217\u8fdb\u53bb,\u5426\u5219\u4e00\u8d77\u88ab\u780d\u6389\u3002"},};